/** Encode `bytes` as a lowercase hex string (no separators). */
export function toHex(bytes: Uint8Array): string {
  let out = '';
  for (const byte of bytes) {
    out += byte.toString(16).padStart(2, '0');
  }
  return out;
}

/** Parse a hex string into bytes; whitespace and `:` separators are ignored. */
export function fromHex(hex: string): Uint8Array {
  const clean = hex.replace(/[\s:]/g, '');
  if (clean.length % 2 !== 0) {
    throw new Error(`Invalid hex string (odd length): ${hex}`);
  }
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    const pair = clean.slice(i * 2, i * 2 + 2);
    const byte = Number.parseInt(pair, 16);
    if (Number.isNaN(byte)) {
      throw new Error(`Invalid hex string: ${hex}`);
    }
    out[i] = byte;
  }
  return out;
}

/** Concatenate byte arrays, in order, into a single new array. */
export function concat(...arrays: Uint8Array[]): Uint8Array {
  const total = arrays.reduce((n, a) => n + a.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const a of arrays) {
    out.set(a, offset);
    offset += a.length;
  }
  return out;
}

/**
 * Repeat `data` until it fills exactly `length` bytes (truncating the last
 * copy). Mirrors the PKCS#12 `S`/`P` expansion in doc/crypto.md.
 */
export function repeatTo(data: Uint8Array, length: number): Uint8Array {
  if (data.length === 0) {
    throw new Error('repeatTo: cannot repeat an empty array');
  }
  const out = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    out[i] = data[i % data.length]!;
  }
  return out;
}

/**
 * BouncyCastle `PKCS12PasswordToBytes`: the UTF-16BE code units of `s`
 * followed by two 0x00 bytes. `"test123"` →
 * `00740065007300740031003200330000` (see doc/crypto.md).
 */
export function utf16beWithNullTerminator(s: string): Uint8Array {
  const bytes = new Uint8Array((s.length + 1) * 2);
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    bytes[i * 2] = (code >> 8) & 0xff;
    bytes[i * 2 + 1] = code & 0xff;
  }
  // The final two bytes are already 0x00 0x00.
  return bytes;
}
